local D=app.params['out'];local f=io.open(D..'/manifest.json','r');local banks=json.decode(f:read('*a'));f:close();for name,a in pairs(banks)do local im=Image{fromFile=D..'/'..name..'.png'};local s=Sprite(a.cw,a.ch,ColorMode.RGB);s.layers[1].name='Actual ColeForge escape / '..name;for n=0,a.frames-1 do if n>0 then s:newEmptyFrame()end;local c=Image(im,Rectangle(n%a.cols*a.cw,math.floor(n/a.cols)*a.ch,a.cw,a.ch));s:newCel(s.layers[1],n+1,c,Point(0,0));s.frames[n+1].duration=name=='ring'and 1/24 or .075 end;local p=s:newSlice(Rectangle(0,0,a.cw,a.ch));p.name='blast-center';p.pivot=Point(a.pivot[1],a.pivot[2]);s:saveAs(D..'/'..name..'.aseprite');s:close()end